/* Internal snapshot regression tests. MQTT continues to use test_edr.c's
 * independent two-byte EDR16 contract. Expected bytes below are literal
 * little-endian fixtures, not generated by the production codec. */
#include "edr.h"

#include <assert.h>
#include <limits.h>
#include <stdio.h>
#include <string.h>

static void assert_filled(const uint8_t *bytes, size_t size)
{
    size_t index;
    for (index = 0U; index < size; ++index) assert(bytes[index] == 0xa5U);
}

static void test_motion(void)
{
    const uint8_t golden[7] = {0xf1U, 0x04U, 0x20U, 0x78U, 0x56U, 0x34U, 0x12U};
    const edr_motion_t input = {1265U, EDR_FAULT_TIMEOUT, UINT32_C(0x12345678)};
    edr_motion_t output = {123U, 45U, 678U};
    edr_motion_t invalid = input;
    uint8_t bytes[EDR_MOTION_SIZE + 1U], before[sizeof(output)];
    size_t size;

    assert(EDR_MOTION_SIZE == sizeof(golden));
    memset(bytes, 0xa5, sizeof(bytes));
    assert(edr_motion_encode(&input, bytes, sizeof(bytes)));
    assert(memcmp(bytes, golden, sizeof(golden)) == 0 && bytes[7] == 0xa5U);
    assert(edr_motion_decode(golden, sizeof(golden), &output));
    assert(output.motor == 1265U && output.faults == EDR_FAULT_TIMEOUT);
    assert(output.command_ms == UINT32_C(0x12345678));

    memcpy(before, &output, sizeof(output));
    for (size = 0U; size <= sizeof(bytes); ++size) {
        if (size == EDR_MOTION_SIZE) continue;
        assert(!edr_motion_decode(bytes, size, &output));
        assert(memcmp(before, &output, sizeof(output)) == 0);
    }
    for (size = 0U; size < EDR_MOTION_SIZE; ++size) {
        memset(bytes, 0xa5, sizeof(bytes));
        assert(!edr_motion_encode(&input, bytes, size));
        assert_filled(bytes, sizeof(bytes));
    }
    invalid.motor = 7U; /* Reserved command; not a valid packed motor word. */
    assert(!edr_motion_encode(&invalid, bytes, sizeof(bytes)));
    assert_filled(bytes, sizeof(bytes));
    invalid = input; invalid.motor |= 0x1000U;
    assert(!edr_motion_encode(&invalid, bytes, sizeof(bytes)));
    invalid = input; invalid.faults = 0x80U;
    assert(!edr_motion_encode(&invalid, bytes, sizeof(bytes)));
    assert_filled(bytes, sizeof(bytes));
    memcpy(bytes, golden, sizeof(golden)); bytes[1] |= 0x10U;
    assert(!edr_motion_decode(bytes, EDR_MOTION_SIZE, &output));
    assert(memcmp(before, &output, sizeof(output)) == 0);
    memcpy(bytes, golden, sizeof(golden)); bytes[2] = 0x80U;
    assert(!edr_motion_decode(bytes, EDR_MOTION_SIZE, &output));
    assert(memcmp(before, &output, sizeof(output)) == 0);
    assert(!edr_motion_encode(NULL, bytes, sizeof(bytes)));
    assert(!edr_motion_encode(&input, NULL, EDR_MOTION_SIZE));
    assert(!edr_motion_decode(NULL, EDR_MOTION_SIZE, &output));
    assert(!edr_motion_decode(golden, EDR_MOTION_SIZE, NULL));
}

static void test_encoder(void)
{
    const uint8_t golden[13] = {0xfeU, 0xffU, 0xffU, 0xffU,
        0x01U, 0x00U, 0x00U, 0x80U, 0x98U, 0xbaU, 0xdcU, 0xfeU, 0x1fU};
    const edr_encoder_t input = {UINT32_C(0xfffffffe), UINT32_C(0x80000001),
        UINT32_C(0xfedcba98), 0x1fU};
    edr_encoder_t output = {123U, 456U, 789U, EDR_ENCODER_VALID};
    edr_encoder_t invalid = {0};
    uint8_t bytes[EDR_ENCODER_SIZE + 1U], before[sizeof(output)];
    size_t size;
    unsigned int flags;

    assert(EDR_ENCODER_SIZE == sizeof(golden));
    memset(bytes, 0xa5, sizeof(bytes));
    assert(edr_encoder_encode(&input, bytes, sizeof(bytes)));
    assert(memcmp(bytes, golden, sizeof(golden)) == 0 && bytes[13] == 0xa5U);
    assert(edr_encoder_decode(golden, sizeof(golden), &output));
    assert(output.left_counts == UINT32_C(0xfffffffe));
    assert(output.right_counts == UINT32_C(0x80000001));
    assert(output.sampled_ms == UINT32_C(0xfedcba98) && output.flags == 0x1fU);
    memcpy(before, &output, sizeof(output));
    for (size = 0U; size <= sizeof(bytes); ++size) {
        if (size == EDR_ENCODER_SIZE) continue;
        assert(!edr_encoder_decode(bytes, size, &output));
        assert(memcmp(before, &output, sizeof(output)) == 0);
    }
    for (size = 0U; size < EDR_ENCODER_SIZE; ++size) {
        memset(bytes, 0xa5, sizeof(bytes));
        assert(!edr_encoder_encode(&input, bytes, size));
        assert_filled(bytes, sizeof(bytes));
    }
    /* Every reserved flag combination is rejected. With VALID clear, only
     * an entirely zero snapshot is canonical, including the sampled time. */
    for (flags = 0U; flags <= UINT8_MAX; ++flags) {
        const bool valid = flags == 0U || (flags <= 31U && flags % 2U == 1U);
        invalid = (edr_encoder_t){0}; invalid.flags = (uint8_t)flags;
        memset(bytes, 0xa5, sizeof(bytes));
        assert(edr_encoder_encode(&invalid, bytes, sizeof(bytes)) == valid);
        if (!valid) assert_filled(bytes, sizeof(bytes));
        memset(bytes, 0, EDR_ENCODER_SIZE); bytes[12] = (uint8_t)flags;
        memcpy(before, &output, sizeof(output));
        assert(edr_encoder_decode(bytes, EDR_ENCODER_SIZE, &output) == valid);
        if (!valid) assert(memcmp(before, &output, sizeof(output)) == 0);
    }
    for (size = 0U; size < 12U; ++size) {
        memset(bytes, 0, EDR_ENCODER_SIZE); bytes[size] = 1U;
        memcpy(before, &output, sizeof(output));
        assert(!edr_encoder_decode(bytes, EDR_ENCODER_SIZE, &output));
        assert(memcmp(before, &output, sizeof(output)) == 0);
    }
    invalid = (edr_encoder_t){1U, 0U, 0U, 0U};
    memset(bytes, 0xa5, sizeof(bytes));
    assert(!edr_encoder_encode(&invalid, bytes, sizeof(bytes)));
    invalid = (edr_encoder_t){0U, 1U, 0U, 0U};
    assert(!edr_encoder_encode(&invalid, bytes, sizeof(bytes)));
    invalid = (edr_encoder_t){0U, 0U, 1U, 0U};
    assert(!edr_encoder_encode(&invalid, bytes, sizeof(bytes)));
    assert_filled(bytes, sizeof(bytes));
    assert(!edr_encoder_encode(NULL, bytes, sizeof(bytes)));
    assert(!edr_encoder_encode(&input, NULL, EDR_ENCODER_SIZE));
    assert(!edr_encoder_decode(NULL, EDR_ENCODER_SIZE, &output));
    assert(!edr_encoder_decode(golden, EDR_ENCODER_SIZE, NULL));
}

static void test_frame(void)
{
    const uint8_t payload[3] = {0x00U, 0xffU, 0x00U};
    const uint8_t golden[5] = {0x4aU, 0x03U, 0x00U, 0xffU, 0x00U};
    uint8_t packet[EDR_HEADER_SIZE + EDR_PAYLOAD_MAX + 1U];
    uint8_t maximum[EDR_PAYLOAD_MAX] = {0};
    edr_frame_t output = {0};
    uint8_t before[sizeof(output)];
    size_t size = 999U, capacity;
    unsigned int header;

    memset(packet, 0xa5, sizeof(packet));
    assert(edr_frame_encode(2U, 1U, payload, sizeof(payload), packet, sizeof(packet), &size));
    assert(size == sizeof(golden) && memcmp(packet, golden, size) == 0);
    assert(packet[size] == 0xa5U);
    assert(edr_frame_decode(packet, size, &output));
    assert(output.source == 2U && output.kind == 1U && output.payload_size == 3U);
    assert(output.p_payload == packet + 2U && memcmp(output.p_payload, payload, 3U) == 0);
    memcpy(before, &output, sizeof(output));
    for (capacity = 0U; capacity <= sizeof(golden) + 1U; ++capacity) {
        if (capacity == sizeof(golden)) continue;
        assert(!edr_frame_decode(packet, capacity, &output));
        assert(memcmp(before, &output, sizeof(output)) == 0);
    }
    for (capacity = 0U; capacity < sizeof(golden); ++capacity) {
        memset(packet, 0xa5, sizeof(packet)); size = 999U;
        assert(!edr_frame_encode(2U, 1U, payload, sizeof(payload), packet, capacity, &size));
        assert(size == 999U); assert_filled(packet, sizeof(packet));
    }
    assert(edr_frame_encode(5U, 7U, NULL, 0U, packet, sizeof(packet), &size));
    assert(size == 2U && packet[0] == 0x7dU && packet[1] == 0U);
    assert(edr_frame_encode(1U, 0U, maximum, sizeof(maximum), packet, sizeof(packet), &size));
    assert(size == 257U && packet[1] == 255U && packet[257] == 0xa5U);
    assert(edr_frame_decode(packet, size, &output) && output.payload_size == 255U);
    memset(packet, 0xa5, sizeof(packet)); size = 999U;
    assert(!edr_frame_encode(0U, 0U, NULL, 0U, packet, sizeof(packet), &size));
    assert(!edr_frame_encode(6U, 0U, NULL, 0U, packet, sizeof(packet), &size));
    assert(!edr_frame_encode(1U, 8U, NULL, 0U, packet, sizeof(packet), &size));
    assert(!edr_frame_encode(1U, 0U, NULL, 1U, packet, sizeof(packet), &size));
    assert(!edr_frame_encode(1U, 0U, payload, SIZE_MAX, packet, sizeof(packet), &size));
    assert(!edr_frame_encode(1U, 0U, payload, 256U, packet, sizeof(packet), &size));
    assert(!edr_frame_encode(1U, 0U, NULL, 0U, NULL, sizeof(packet), &size));
    assert(!edr_frame_encode(1U, 0U, NULL, 0U, packet, sizeof(packet), NULL));
    assert(size == 999U); assert_filled(packet, sizeof(packet));
    assert(!edr_frame_decode(NULL, 2U, &output));
    assert(!edr_frame_decode(packet, 2U, NULL));
    for (header = 0U; header <= UINT8_MAX; ++header) {
        const bool valid = header >= 64U && header < 128U &&
                           header % 8U >= 1U && header % 8U <= 5U;
        packet[0] = (uint8_t)header; packet[1] = 0U;
        memcpy(before, &output, sizeof(output));
        assert(edr_frame_decode(packet, 2U, &output) == valid);
        if (!valid) assert(memcmp(before, &output, sizeof(output)) == 0);
    }
}

static void test_clock_and_count_boundaries(void)
{
    int32_t delta = 42;
    assert(edr_count_delta(0U, UINT32_MAX, &delta) && delta == 1);
    assert(edr_count_delta(UINT32_MAX, 0U, &delta) && delta == -1);
    assert(edr_count_delta(UINT32_C(0x7fffffff), 0U, &delta) && delta == INT32_MAX);
    assert(edr_count_delta(UINT32_C(0x80000001), 0U, &delta) && delta == -INT32_MAX);
    delta = 42;
    assert(!edr_count_delta(UINT32_C(0x80000000), 0U, &delta) && delta == 42);
    assert(!edr_count_delta(0U, UINT32_C(0x80000000), &delta) && delta == 42);
    assert(!edr_count_delta(0U, 0U, NULL));
    assert(edr_age_is_fresh(3U, UINT32_C(0xfffffffe), 5U));
    assert(!edr_age_is_fresh(3U, UINT32_C(0xfffffffe), 4U));
    assert(edr_age_is_fresh(100U, 100U, 0U));
    assert(!edr_age_is_fresh(100U, 101U, 100U));
    assert(!edr_age_is_fresh(0U, 0U, UINT32_C(0x80000000)));
}

int main(void)
{
    test_motion();
    test_encoder();
    test_frame();
    test_clock_and_count_boundaries();
    puts("Internal snapshot codecs: golden bytes, full-width counts, strict bounds and failure preservation PASS");
    return 0;
}
